<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Commercial\Enterprise;
$enterprise=new Enterprise($db,$core->migrator());
$subscriber=p13_user('enterprise-subscriber');$manager=p13_user('enterprise-manager');$sponsorManager=p13_user('enterprise-sponsor-only');$analyst=p13_user('enterprise-analyst');
get_userdata($manager)->add_cap(Enterprise::CAPABILITY);get_userdata($sponsorManager)->add_cap('aish_manage_sponsors');get_userdata($analyst)->add_cap('aish_view_commercial_metrics');
$initial=Enterprise::snapshot();$config=['enabled'=>true,'translations'=>['zh_CN'=>['title'=>'QA 企业支持','description'=>'仅用于隔离测试的服务咨询。由人工查看本次需求。'],'en_US'=>['title'=>'QA enterprise support','description'=>'Synthetic isolated inquiry fixture for manual handling.']]];
$input=['name'=>'Synthetic QA contact','email'=>'phase13-'.$run.'@example.invalid','message'=>'Synthetic private inquiry, not a real request or customer.','website'=>''];$key=hash('sha256',$run.':inquiry');$id=0;
p13_case('enterprise_disabled_and_language_specific_explicit_copy',function()use($enterprise,$initial,$config,$input,$key,$admin){p13_assert(!$initial['enabled'],'Enterprise section starts disabled');if($initial['revision']===0){p13_assert($initial===Enterprise::defaults(),'No invented services or default inquiry copy');}p13_assert(Enterprise::publicCopy('zh_CN')===null,'Default enterprise section absent');p13_reject(fn()=>$enterprise->receive($input,'en_US',$key),'Disabled service cannot receive bypass');wp_set_current_user($admin);$one=$config;$one['translations']['zh_CN']=['title'=>'','description'=>''];$s=$enterprise->saveConfig($one,$initial['revision']);p13_assert(Enterprise::publicCopy('en_US')!==null&&Enterprise::publicCopy('zh_CN')===null,'No fictional translation fallback');p13_reject(fn()=>$enterprise->saveConfig($config,$initial['revision']),'Stale config cannot overwrite current');$enterprise->saveConfig($config,$s['revision']);});
p13_case('enterprise_private_inbox_idempotency_and_no_business_side_effect',function()use($enterprise,$input,$key,$db,$wpdb,$admin,&$id){wp_set_current_user(0);$beforeSkills=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('skills'));$beforeMail=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('notification_outbox'));$id=$enterprise->receive($input,'en_US',$key);p13_assert($enterprise->receive($input,'en_US',$key)===$id,'Same request retry returns same private record');$changed=$input;$changed['message'].=' Changed';p13_reject(fn()=>$enterprise->receive($changed,'en_US',$key),'Same key different content conflicts');$p=get_post($id);p13_assert($p instanceof WP_Post&&$p->post_type==='aish_message'&&$p->post_status==='private'&&(int)$p->post_author===0,'Native private Inbox without account claim');p13_assert(get_post_meta($id,'_aish_message_kind',true)==='enterprise','Independent inquiry subtype');p13_assert(get_post_meta($id,'_aish_submission_version',true)==='','Not a Skill submission');p13_assert((int)$db->value("SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE meta_key='_aish_enterprise_request' AND meta_value=%s",[$key])===1,'Exact one request relation');p13_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->table('skills'))===$beforeSkills,'No Skill generated or published');p13_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->table('notification_outbox'))===$beforeMail,'No email generated');wp_set_current_user($admin);p13_assert(count($enterprise->history($id))===1,'One receipt audit despite retry');});
p13_case('enterprise_input_bounds_honeypot_and_no_url_side_effects',function()use($enterprise,$input,$run,$db,$wpdb){$before=(int)$db->value("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='aish_message'");foreach([['email'=>'not-an-email'],['website'=>'bot'],['message'=>str_repeat('界',3001)],['github_url'=>'https://github.com/mtccv/Skills-ak'],['message'=>[]],['name'=>[]]]as$i=>$bad){p13_reject(fn()=>$enterprise->receive(array_replace($input,$bad),'en_US',hash('sha256',$run.':bad:'.$i)),'Invalid inquiry rejected');}p13_assert((int)$db->value("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='aish_message'")===$before,'Rejected inputs create no partial posts');p13_reject(fn()=>$enterprise->receive($input,'fr_FR',hash('sha256',$run.':locale')),'Unsupported language rejected');});
p13_case('enterprise_least_privilege_native_editor_and_object_isolation',function()use($enterprise,$subscriber,$sponsorManager,$analyst,$manager,$admin,$input,$id){foreach([$subscriber,$sponsorManager,$analyst]as$user){wp_set_current_user($user);p13_reject(fn()=>$enterprise->detail($id),'Other capability cannot read inquiry PII');p13_reject(fn()=>$enterprise->listing(),'Other capability cannot list inquiry PII');p13_reject(fn()=>$enterprise->moderate($id,1,'closed','Unapproved read'),'Other capability cannot handle inquiry');}wp_set_current_user($manager);p13_assert($enterprise->detail($id)['meta']['_aish_sender_email']===$input['email'],'Dedicated manager can read private contact');p13_assert(!current_user_can('aish_manage_skills')&&!current_user_can('aish_manage_sponsors'),'Inquiry manager receives no content or sponsor management');p13_assert(!current_user_can('edit_post',$id)&&!current_user_can('delete_post',$id),'Native generic editing and deletion cannot bypass workflow');wp_set_current_user($admin);p13_assert(!current_user_can('edit_post',$id)&&!current_user_can('delete_post',$id),'Native administrator also uses managed workflow');p13_reject(fn()=>$enterprise->detail(PHP_INT_MAX),'Unknown object rejected');});
p13_case('enterprise_moderation_cas_audit_and_aggregate_without_pii',function()use($enterprise,$id,$manager,$analyst,$input,$db,$admin){wp_set_current_user($manager);$row=$enterprise->detail($id);$revision=(int)$row['meta']['_aish_enterprise_revision'];$enterprise->moderate($id,$revision,'reviewing','Private QA handling note');$current=$enterprise->detail($id);p13_assert($current['meta']['_aish_message_state']==='reviewing'&&(int)$current['meta']['_aish_enterprise_revision']===$revision+1,'Revision and state committed together');p13_reject(fn()=>$enterprise->moderate($id,$revision,'closed','Stale'),'Stale handling rejected');$enterprise->moderate($id,$revision+1,'reviewing','Private QA handling note');p13_assert((int)$enterprise->detail($id)['meta']['_aish_enterprise_revision']===$revision+1,'Same current outcome is no-op');p13_assert(count($enterprise->history($id))===2,'Receipt and moderation audit only');$raw=$db->rows('SELECT metadata_json FROM '.$db->table('workflow_events')." WHERE subject_type='enterprise_inquiry' AND subject_id=%d",[$id]);$json=wp_json_encode($raw);foreach([$input['email'],$input['name'],$input['message'],'Private QA handling note']as$private)p13_assert(!str_contains($json,$private),'Audit excludes raw personal content');wp_set_current_user($analyst);$count=$enterprise->countReceived(gmdate('Y-m-d 00:00:00'),gmdate('Y-m-d 00:00:00',time()+DAY_IN_SECONDS));p13_assert($count>=1,'Read-only aggregate count accessible independently');p13_reject(fn()=>$enterprise->detail($id),'Aggregate capability never grants details');});
wp_set_current_user($admin);$enterprise->saveConfig(['enabled'=>false,'translations'=>$initial['translations']],Enterprise::snapshot()['revision']);
p13_report('Real WordPress/MySQL private enterprise Inbox, deduplication, state revisions, capability separation, input validation and native editing restrictions; synthetic contacts, no external mail or API.');
